Map<String, int> fn0(List<int> costs, int k) {
  final sorted = List<int>.from(costs)..sort();
  int kthSmallestCost;
  if (k <= 0) {
    kthSmallestCost = -1;
  } else if (k > sorted.length) {
    kthSmallestCost = -1;
  } else {
    kthSmallestCost = sorted[k - 1];
  }

  int total = 0;
  if (kthSmallestCost != -1) {
    for (int i = 0; i < costs.length; i++) {
      if (costs[i] <= kthSmallestCost) {
        total++;
      }
    }
  }

  return {
    'kthSmallestCost': kthSmallestCost,
    'totalElementsLE': total,
  };
}
